<?php
/** Handle database-backed actions shared by StayEase modules. */
function handle_module_action(string $action, ?PDO $pdo): void {
    $actions=['save_homestay','set_homestay_status','save_description','save_promotion','set_promotion_status','save_pricing_rule','set_pricing_rule_status','create_booking','change_booking_status','cancel_booking','create_block','remove_block','submit_payment','verify_payment','refund_payment','save_review','moderate_review','reply_review','save_profile'];
    if (!in_array($action,$actions,true)) return;
    if (!current_user()) { flash('Sign in to continue.','error'); go('?page=login'); }
    $staffActions=['save_homestay','set_homestay_status','save_description','save_promotion','set_promotion_status','save_pricing_rule','set_pricing_rule_status','change_booking_status','create_block','remove_block','verify_payment','refund_payment','moderate_review','reply_review'];
    if (in_array($action,$staffActions,true) && current_user()['role']!=='Staff') { http_response_code(403); exit('Staff access only.'); }
    if (!$pdo) { flash('This action needs an active StayEase database connection.','error'); go('?page=home'); }
    try {
        if ($action==='save_profile') {
            $name=trim($_POST['full_name']??''); $email=strtolower(trim($_POST['email']??'')); $phone=trim($_POST['phone']??'');
            if (!$name || !filter_var($email,FILTER_VALIDATE_EMAIL) || !$phone) { flash('Enter a valid name, email and phone number.','error'); go('?page=profile'); }
            $q=$pdo->prepare('UPDATE users SET full_name=?,email=?,phone=? WHERE user_id=?'); $q->execute([$name,$email,$phone,current_user()['user_id']]);
            $_SESSION['user']['full_name']=$name; $_SESSION['user']['email']=$email; flash('Your profile was updated.'); go('?page=profile');
        }
        if ($action==='save_homestay') {
            $id=(int)($_POST['homestay_id']??0); $name=trim($_POST['name']??'');$state=trim($_POST['state']??'');$city=trim($_POST['city']??'');$address=trim($_POST['address']??'');$description=trim($_POST['description']??'');
            $bedrooms=(int)($_POST['bedrooms']??0);$bathrooms=(int)($_POST['bathrooms']??0);$capacity=(int)($_POST['capacity']??0);$price=(float)($_POST['base_price']??0);$status=$_POST['status']??'Active';
            if (!$name||!$state||!$city||!$address||$bedrooms<1||$bathrooms<1||$capacity<1||$price<=0||!in_array($status,['Active','Maintenance','Inactive'],true)) { flash('Complete all required homestay fields with valid values.','error'); go('?page=homestay-form'.($id?'&id='.$id:'')); }
            if ($id) {$q=$pdo->prepare('UPDATE homestays SET name=?,state=?,city=?,address=?,description=?,bedrooms=?,bathrooms=?,capacity=?,base_price=?,status=? WHERE homestay_id=?');$q->execute([$name,$state,$city,$address,$description,$bedrooms,$bathrooms,$capacity,$price,$status,$id]);}
            else {$q=$pdo->prepare('INSERT INTO homestays(name,state,city,address,description,bedrooms,bathrooms,capacity,base_price,status) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$name,$state,$city,$address,$description,$bedrooms,$bathrooms,$capacity,$price,$status]);$id=(int)$pdo->lastInsertId();}
            $image=trim($_POST['image_path']??'');
            if ($image!=='') {$q=$pdo->prepare('SELECT image_id FROM homestay_images WHERE homestay_id=? AND is_cover=1 LIMIT 1');$q->execute([$id]);$imgId=$q->fetchColumn();if($imgId){$u=$pdo->prepare('UPDATE homestay_images SET image_path=? WHERE image_id=?');$u->execute([$image,$imgId]);}else{$u=$pdo->prepare('INSERT INTO homestay_images(homestay_id,image_path,is_cover,sort_order) VALUES(?,?,1,0)');$u->execute([$id,$image]);}}
            flash($image!==''?'Homestay details and cover image saved.':'Homestay details saved.');go('?page=homestays-admin');
        }
        if ($action==='set_homestay_status') {
            $id=(int)($_POST['homestay_id']??0);$status=$_POST['status']??'';
            if(!in_array($status,['Active','Maintenance','Inactive'],true)) {flash('Choose a valid listing status.','error');go('?page=homestays-admin');}
            $q=$pdo->prepare('UPDATE homestays SET status=? WHERE homestay_id=?');$q->execute([$status,$id]);flash('Homestay status updated.');go('?page=homestays-admin');
        }
        if ($action==='save_description') {$id=(int)($_POST['homestay_id']??0);$description=trim($_POST['description']??'');if(!$id||strlen($description)>5000){flash('Select a homestay and keep its description under 5,000 characters.','error');go('?page=ai-description');}$q=$pdo->prepare('UPDATE homestays SET description=? WHERE homestay_id=?');$q->execute([$description,$id]);flash('Homestay description saved.');go('?page=ai-description&id='.$id);}
        if ($action==='save_promotion') {
            $id=(int)($_POST['promo_id']??0);$code=strtoupper(trim($_POST['code']??''));$desc=trim($_POST['description']??'');$type=$_POST['discount_type']??'Percent';$value=(float)($_POST['discount_value']??0);$minNights=max(1,(int)($_POST['min_nights']??1));$minAmount=max(0,(float)($_POST['min_amount']??0));$from=$_POST['valid_from']??'';$to=$_POST['valid_to']??'';$limit=(int)($_POST['usage_limit']??0);$status=$_POST['status']??'Active';
            if(!$code||!in_array($type,['Percent','Fixed'],true)||$value<=0||($type==='Percent'&&$value>100)||!$from||!$to||$to<$from||$limit<1||!in_array($status,['Active','Inactive'],true)){flash('Check the promotion code, discount, dates and usage limit.','error');go('?page=promotion-form'.($id?'&id='.$id:''));}
            if($id){$q=$pdo->prepare('UPDATE promo_codes SET code=?,description=?,discount_type=?,discount_value=?,min_nights=?,min_amount=?,valid_from=?,valid_to=?,usage_limit=?,status=? WHERE promo_id=?');$q->execute([$code,$desc,$type,$value,$minNights,$minAmount,$from,$to,$limit,$status,$id]);}
            else{$q=$pdo->prepare('INSERT INTO promo_codes(code,description,discount_type,discount_value,min_nights,min_amount,valid_from,valid_to,usage_limit,status) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$code,$desc,$type,$value,$minNights,$minAmount,$from,$to,$limit,$status]);}
            flash('Promotion saved.');go('?page=promotions');
        }
        if ($action==='set_promotion_status') {$id=(int)($_POST['promo_id']??0);$status=($_POST['status']??'')==='Inactive'?'Inactive':'Active';$q=$pdo->prepare('UPDATE promo_codes SET status=? WHERE promo_id=?');$q->execute([$status,$id]);flash('Promotion status updated.');go('?page=promotions');}
        if ($action==='save_pricing_rule') {$id=(int)($_POST['rule_id']??0);$home=(int)($_POST['homestay_id']??0);$name=trim($_POST['rule_name']??'');$type=$_POST['rule_type']??'';$start=$_POST['start_date']??'';$end=$_POST['end_date']??'';$nights=(int)($_POST['min_nights']??0);$adjust=(float)($_POST['adjust_percent']??0);$status=$_POST['status']??'Active';if(!$name||!in_array($type,['Seasonal','Weekend','Long Stay'],true)||$adjust < -100||$adjust>300||!in_array($status,['Active','Inactive'],true)||($type==='Seasonal'&&(!$start||!$end||$end<$start))||($type==='Long Stay'&&$nights<1)){flash('Check the pricing rule name, type and required dates or minimum nights.','error');go('?page=pricing-rules');}$start=$type==='Seasonal'?$start:null;$end=$type==='Seasonal'?$end:null;$nights=$type==='Long Stay'?$nights:null;$home=$home?:null;if($id){$q=$pdo->prepare('UPDATE pricing_rules SET homestay_id=?,rule_name=?,rule_type=?,start_date=?,end_date=?,min_nights=?,adjust_percent=?,status=? WHERE rule_id=?');$q->execute([$home,$name,$type,$start,$end,$nights,$adjust,$status,$id]);}else{$q=$pdo->prepare('INSERT INTO pricing_rules(homestay_id,rule_name,rule_type,start_date,end_date,min_nights,adjust_percent,status) VALUES(?,?,?,?,?,?,?,?)');$q->execute([$home,$name,$type,$start,$end,$nights,$adjust,$status]);}flash('Pricing rule saved.');go('?page=pricing-rules');}
        if ($action==='set_pricing_rule_status') {$id=(int)($_POST['rule_id']??0);$status=($_POST['status']??'')==='Inactive'?'Inactive':'Active';$q=$pdo->prepare('UPDATE pricing_rules SET status=? WHERE rule_id=?');$q->execute([$status,$id]);flash('Pricing rule status updated.');go('?page=pricing-rules');}
        if ($action==='create_booking') {
            $home=(int)($_POST['homestay_id']??0);$in=$_POST['check_in']??'';$out=$_POST['check_out']??'';$guests=(int)($_POST['guests']??1);$source=current_user()['role']==='Staff'?($_POST['booking_source']??'Online'):'Online';
            if(!in_array($source,['Online','Walk-in','Phone'],true))$source='Online';
            $q=$pdo->prepare("SELECT * FROM homestays WHERE homestay_id=? AND status='Active'");$q->execute([$home]);$stay=$q->fetch();
            if(!$stay||!$in||!$out||$out<=$in||$in<date('Y-m-d')||$guests<1||$guests>(int)$stay['capacity']){flash('Choose an active homestay, valid future dates and a guest count within capacity.','error');go('?page=booking-flow&step=dates');}
            $nights=(int)((strtotime($out)-strtotime($in))/86400);
            $q=$pdo->prepare("SELECT COUNT(*) FROM bookings WHERE homestay_id=? AND status IN ('Pending','Confirmed','Checked-in') AND check_in < ? AND check_out > ?");$q->execute([$home,$out,$in]);
            $q2=$pdo->prepare("SELECT COUNT(*) FROM blocked_dates WHERE homestay_id=? AND status='Active' AND start_date < ? AND end_date >= ?");$q2->execute([$home,$out,$in]);
            if((int)$q->fetchColumn()+(int)$q2->fetchColumn()>0){flash('Those dates are not available. Choose another date range.','error');go('?page=booking-flow&step=dates');}
            $q=$pdo->prepare("SELECT * FROM pricing_rules WHERE status='Active' AND (homestay_id=? OR homestay_id IS NULL)");$q->execute([$home]);$rules=$q->fetchAll();$roomTotal=0.0;$longDiscount=0.0;
            for($day=strtotime($in);$day<strtotime($out);$day=strtotime('+1 day',$day)){$date=date('Y-m-d',$day);$night=(float)$stay['base_price'];foreach($rules as $rule){if($rule['rule_type']==='Seasonal'&&$rule['start_date']<=$date&&$rule['end_date']>=$date)$night*=1+(float)$rule['adjust_percent']/100;if($rule['rule_type']==='Weekend'&&(int)date('N',$day)>=6)$night*=1+(float)$rule['adjust_percent']/100;} $roomTotal+=$night;}
            foreach($rules as $rule)if($rule['rule_type']==='Long Stay'&&$nights>=(int)$rule['min_nights'])$longDiscount=max($longDiscount,$roomTotal*(float)$rule['adjust_percent']/-100);
            $promoId=null;$promoDiscount=0.0;$code=strtoupper(trim($_POST['promo_code']??''));$eligibleTotal=max(0,$roomTotal-$longDiscount);
            if($code!==''){$q=$pdo->prepare("SELECT p.*,(SELECT COUNT(*) FROM bookings b WHERE b.promo_id=p.promo_id AND b.status<>'Cancelled') used FROM promo_codes p WHERE p.code=? AND p.status='Active' AND p.valid_from<=CURDATE() AND p.valid_to>=CURDATE()");$q->execute([$code]);$promo=$q->fetch();if(!$promo||(int)$promo['used'] >= (int)$promo['usage_limit']||$nights<(int)$promo['min_nights']||$eligibleTotal<(float)$promo['min_amount']){flash('That promo code is invalid, expired, exhausted or does not meet its minimum stay or spend.','error');go('?page=booking-flow&step=review');}$promoId=(int)$promo['promo_id'];$promoDiscount=$promo['discount_type']==='Percent'?$eligibleTotal*(float)$promo['discount_value']/100:min($eligibleTotal,(float)$promo['discount_value']);}
            $total=max(0,$eligibleTotal-$promoDiscount);$userId=(int)current_user()['user_id'];
            if(current_user()['role']==='Staff'){$target=(int)($_POST['customer_id']??0);$q=$pdo->prepare("SELECT user_id FROM users WHERE user_id=? AND role='User' AND status='Active'");$q->execute([$target]);if(!$q->fetchColumn()){flash('Select an active customer account for this staff booking.','error');go('?page=booking-flow&step=dates');}$userId=$target;}
            $createdBy=$source==='Online'?null:(int)current_user()['user_id'];
            $pdo->beginTransaction();$lock=$pdo->prepare('SELECT homestay_id FROM homestays WHERE homestay_id=? FOR UPDATE');$lock->execute([$home]);$q=$pdo->prepare("SELECT booking_id FROM bookings WHERE homestay_id=? AND status IN ('Pending','Confirmed','Checked-in') AND check_in < ? AND check_out > ? FOR UPDATE");$q->execute([$home,$out,$in]);if($q->fetch()){ $pdo->rollBack();flash('Those dates were just booked. Choose another date range.','error');go('?page=booking-flow&step=dates');}
            $q=$pdo->prepare('INSERT INTO bookings(user_id,homestay_id,promo_id,created_by,check_in,check_out,guests,room_total,rule_discount,promo_discount,total_price,status,booking_source) VALUES(?,?,?,?,?,?,?,?,?,?,?,\'Pending\',?)');$q->execute([$userId,$home,$promoId,$createdBy,$in,$out,$guests,$roomTotal,$longDiscount,$promoDiscount,$total,$source]);$bookingId=(int)$pdo->lastInsertId();$pdo->commit();
            if(!empty($_POST['draft_id'])){$q=$pdo->prepare('DELETE FROM booking_drafts WHERE draft_id=? AND user_id=?');$q->execute([(int)$_POST['draft_id'],$userId]);}
            flash('Booking created. Submit payment to complete the request.');go('?page=my-booking&id='.$bookingId);
        }
        if ($action==='change_booking_status') {$id=(int)($_POST['booking_id']??0);$status=$_POST['status']??'';if(!in_array($status,['Pending','Confirmed','Checked-in','Checked-out','Cancelled'],true)){flash('Choose a valid booking status.','error');go('?page=booking-history');}$q=$pdo->prepare('UPDATE bookings SET status=?,cancelled_at=IF(?=\'Cancelled\',NOW(),NULL) WHERE booking_id=?');$q->execute([$status,$status,$id]);flash('Booking status updated.');go('?page=booking-detail&id='.$id);}
        if ($action==='cancel_booking') {$id=(int)($_POST['booking_id']??0);$q=$pdo->prepare("UPDATE bookings SET status='Cancelled',cancelled_at=NOW(),cancel_reason='Cancelled by customer' WHERE booking_id=? AND user_id=? AND status IN ('Pending','Confirmed')");$q->execute([$id,current_user()['user_id']]);flash($q->rowCount()?'Booking cancelled. Contact StayEase if you have already paid.':'This booking can no longer be cancelled online.','error');go('?page=my-booking&id='.$id);}
        if ($action==='create_block') {$home=(int)($_POST['homestay_id']??0);$start=$_POST['start_date']??'';$end=$_POST['end_date']??'';$reason=$_POST['reason']??'Other';$note=trim($_POST['note']??'');if(!$start||$start<date('Y-m-d')||!$end||$end<$start||!in_array($reason,['Maintenance','Company Use','Other'],true)){flash('Enter a valid future blocked date range and reason.','error');go('?page=blocked-date-form');}$pdo->beginTransaction();$lock=$pdo->prepare('SELECT homestay_id FROM homestays WHERE homestay_id=? FOR UPDATE');$lock->execute([$home]);if(!$lock->fetch()){$pdo->rollBack();flash('Homestay not found.','error');go('?page=blocked-date-form');}$q=$pdo->prepare("SELECT booking_id FROM bookings WHERE homestay_id=? AND status IN ('Pending','Confirmed','Checked-in') AND check_in <= ? AND check_out > ? FOR UPDATE");$q->execute([$home,$end,$start]);if($q->fetch()){$pdo->rollBack();flash('This range overlaps an active booking.','error');go('?page=blocked-date-form');}$q=$pdo->prepare('INSERT INTO blocked_dates(homestay_id,created_by,start_date,end_date,reason,note) VALUES(?,?,?,?,?,?)');$q->execute([$home,current_user()['user_id'],$start,$end,$reason,$note?:null]);$pdo->commit();flash('Dates blocked.');go('?page=availability-calendar');}
        if ($action==='remove_block') {$id=(int)($_POST['block_id']??0);$q=$pdo->prepare("UPDATE blocked_dates SET status='Removed' WHERE block_id=?");$q->execute([$id]);flash('Blocked dates removed.');go('?page=availability-calendar');}
        if ($action==='submit_payment') {$booking=(int)($_POST['booking_id']??0);$method=$_POST['payment_method']??'';$reference=trim($_POST['reference_no']??'');$methods=['Online Banking','E-Wallet','Bank Transfer','Cash'];$q=$pdo->prepare('SELECT b.* FROM bookings b WHERE b.booking_id=? AND (b.user_id=? OR ?)');$q->execute([$booking,current_user()['user_id'],current_user()['role']==='Staff']);$row=$q->fetch();if(!$row||!in_array($method,$methods,true)||$row['status']==='Cancelled'){flash('Choose a valid booking and payment method.','error');go('?page=payments-customer');}$q=$pdo->prepare("SELECT COUNT(*) FROM payments WHERE booking_id=? AND status='Pending'");$q->execute([$booking]);if((int)$q->fetchColumn()){flash('A payment for this booking is already awaiting staff verification.','error');go('?page=payments-customer');}$q=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM payments WHERE booking_id=? AND status='Paid'");$q->execute([$booking]);$paid=(float)$q->fetchColumn();$due=(float)$row['total_price']-$paid;if($due<=0){flash('This booking has no outstanding balance.','error');go('?page=payments-customer');}$type=$paid>0?'Balance':'Full';$q=$pdo->prepare("INSERT INTO payments(booking_id,amount,payment_type,payment_method,reference_no,status) VALUES(?,?,?,?,?, 'Pending')");$q->execute([$booking,$due,$type,$method,$reference?:null]);flash('Payment submitted for staff verification.');go('?page=payments-customer');}
        if ($action==='verify_payment') {$id=(int)($_POST['payment_id']??0);$status=$_POST['status']??'';if(!in_array($status,['Paid','Rejected'],true)){flash('Choose Paid or Rejected.','error');go('?page=payments-admin');}$pdo->beginTransaction();$q=$pdo->prepare('UPDATE payments SET status=?,verified_by=?,paid_at=IF(?=\'Paid\',NOW(),paid_at) WHERE payment_id=? AND status=\'Pending\'');$q->execute([$status,current_user()['user_id'],$status,$id]);if($status==='Paid'&&$q->rowCount()){$q2=$pdo->prepare('SELECT booking_id FROM payments WHERE payment_id=?');$q2->execute([$id]);$booking=(int)$q2->fetchColumn();$q3=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM payments WHERE booking_id=? AND status='Paid'");$q3->execute([$booking]);$q4=$pdo->prepare('SELECT total_price FROM bookings WHERE booking_id=?');$q4->execute([$booking]);if((float)$q3->fetchColumn()>=(float)$q4->fetchColumn()){$u=$pdo->prepare("UPDATE bookings SET status='Confirmed' WHERE booking_id=? AND status='Pending'");$u->execute([$booking]);}}$pdo->commit();flash('Payment review saved.');go('?page=payments-admin');}
        if ($action==='refund_payment') {$id=(int)($_POST['payment_id']??0);$amount=(float)($_POST['refund_amount']??0);$note=trim($_POST['remarks']??'');$q=$pdo->prepare("SELECT amount,status FROM payments WHERE payment_id=?");$q->execute([$id]);$payment=$q->fetch();if(!$payment||$payment['status']!=='Paid'||$amount<=0||$amount>(float)$payment['amount']){flash('Refund must be greater than zero and cannot exceed the paid amount.','error');go('?page=payments-admin');}$q=$pdo->prepare("UPDATE payments SET status='Refunded',refund_amount=?,remarks=?,verified_by=? WHERE payment_id=?");$q->execute([$amount,$note?:null,current_user()['user_id'],$id]);flash('Refund recorded.');go('?page=payments-admin');}
        if ($action==='save_review') {$booking=(int)($_POST['booking_id']??0);$rating=(int)($_POST['rating']??0);$comment=trim($_POST['comment']??'');$q=$pdo->prepare("SELECT booking_id FROM bookings WHERE booking_id=? AND user_id=? AND status='Checked-out'");$q->execute([$booking,current_user()['user_id']]);if(!$q->fetchColumn()||$rating<1||$rating>5||strlen($comment)<5){flash('Reviews require a completed stay, a 1–5 star rating and a short comment.','error');go('?page=reviews-customer');}$q=$pdo->prepare('INSERT INTO reviews(booking_id,rating,comment,status) VALUES(?,?,?,\'Visible\') ON DUPLICATE KEY UPDATE rating=VALUES(rating),comment=VALUES(comment)');$q->execute([$booking,$rating,$comment]);flash('Your review was saved.');go('?page=reviews-customer');}
        if ($action==='moderate_review') {$id=(int)($_POST['review_id']??0);$status=($_POST['status']??'')==='Hidden'?'Hidden':'Visible';$q=$pdo->prepare('UPDATE reviews SET status=? WHERE review_id=?');$q->execute([$status,$id]);flash('Review visibility updated.');go('?page=reviews-admin');}
        if ($action==='reply_review') {$id=(int)($_POST['review_id']??0);$reply=trim($_POST['staff_reply']??'');if(!$reply){flash('Enter a reply before saving.','error');go('?page=reviews-admin');}$q=$pdo->prepare('UPDATE reviews SET staff_reply=?,replied_by=?,replied_at=NOW() WHERE review_id=?');$q->execute([$reply,current_user()['user_id'],$id]);flash('Reply saved.');go('?page=reviews-admin');}
    } catch (Throwable $e) {
        if ($pdo && $pdo->inTransaction()) $pdo->rollBack();
        flash('Could not complete that action. Check the information and try again.','error');
        go('?page='.match($action){'save_homestay','set_homestay_status'=>'homestays-admin','save_description'=>'ai-description','save_promotion','set_promotion_status'=>'promotions','save_pricing_rule','set_pricing_rule_status'=>'pricing-rules','create_booking','change_booking_status'=>'booking-history','cancel_booking'=>'bookings','create_block','remove_block'=>'availability-calendar','submit_payment','verify_payment','refund_payment'=>'payments-admin','save_review','moderate_review','reply_review'=>'reviews-customer','save_profile'=>'profile',default=>'home'});
    }
}
